const P = {"tool": "Fault Injection and Recovery Laboratory", "tasks": [{"C": 1, "T": 10}, {"C": 2, "T": 23}, {"C": 3, "T": 50}]};

function demoMain(P){
  var U=0, ti; for(ti=0; ti<P.tasks.length; ti++) U+=P.tasks[ti].C/P.tasks[ti].T;
  var n=P.tasks.length, bound=n*(Math.pow(2,1/n)-1);
  return 'Rate-monotonic analysis ('+P.tool+'): utilization U='+U.toFixed(3)+' Liu-Layland bound='+bound.toFixed(3)+' verdict='+(U<=bound?'SCHEDULABLE (sufficient test passes)':'INCONCLUSIVE (requires exact response-time test)');
}
console.log(demoMain(P));

